 for qi,a,d,al in zip(q,[0,0,0,.0825,-.0825,0,.088],[.333,0,.316,0,.384,0,0],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]):
  A=np.eye(4);A[:3,:3]=Rot.from_euler('x',al).as_matrix();A[0,3]=a
  B=np.eye(4);B[:3,:3]=Rot.from_euler('z',qi).as_matrix();B[2,3]=d
  T=T@A@B
 return T

def state(): return np.array(obs.meta['proprio']['now'])
def movej(q,secs=2,grip=None,base=None,torso=0):
 s=state(); start=s[4:11]; q=np.array(q)
